    distance = max_distance_from_source[target]
    while path[-1] != source:
        for node, dist in dijkstra(graph, target).items():
            if dist == distance and node != source:
                path.append(node)
                distance -= dist
                target = node
                break
    while path:
        node = path.pop(0)
        for neighbor, _ in graph[node]:
            if neighbor == target:
                return (distance, path + [target])
    return (float('inf'), None)
