        if path is None:
            path = [node]
        visited.add(node)
        if node == target:
            return path
        for neighbor, weight in graph.get(node, []):
            if neighbor not in visited:
                new_path = path + [neighbor]
                result = bfs_or_dfs(neighbor, target, visited.copy(), new_path)
                if result:
                    return result
        return None
